// Digi's World and Performance: Sailing Tweaks, Vein Mining, Fog Reducer, Smoke Reducer, Pickable Lights, Hide Wisp, Sound Levels, Plant Growth Fix, Farm Performance, Smart Save, Spawner Restore, Lag Meter.
// One plugin and one settings file for all of them: F1 shows a switch per sub-mod at the top, then each sub-mod's
// settings under its name. Generated by make_combined.py; the sub-mods' code is in Modules/.
using BepInEx;
using DigiCore;

namespace DigiWorld
{
    [BepInPlugin(Guid, Name, Version)]
    [BepInDependency("Searica.Valheim.TerrainTools", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ValheimLegends", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("cdev.equipmentslots", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("com.alan.bettersmelter", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ishid4.mods.betterarchery", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("randyknapp.mods.epicloot", BepInDependency.DependencyFlags.SoftDependency)]
    public class Plugin : DigiPlugin
    {
        public const string Guid = "digi.valheim.world";
        public const string Name = "Digi's World and Performance";
        public const string Version = "1.0.21";

        // The modpack's settings files, put in place once (PackSeed.cs) before any sub-mod reads its settings.
        protected override void Awake()
        {
            PackSeed.Run(Logger);
            // This plugin's own settings file was read when it was made (before Awake): once more, in case the pack's
            // copy was just put there (a fresh install), or its defaults would be saved over it.
            if (System.IO.File.Exists(Config.ConfigFilePath)) Config.Reload();
            base.Awake();
        }

        protected override ModuleInfo[] Modules { get; } =
        {
            new ModuleInfo(typeof(global::SailingTweaks.Plugin), "Sailing Tweaks", "digi.valheim.sailingtweaks", "Tailwind while steering, faster ships, no wave damage and more.", null, true),
            new ModuleInfo(typeof(global::VeinMining.Plugin), "Vein Mining", "digi.valheim.veinmining", "Hold Left Alt while mining: when one piece breaks, the whole ore deposit breaks, with full XP.", null, true),
            new ModuleInfo(typeof(global::FogReducer.Plugin), "Fog Reducer", "digi.valheim.fogreducer", "A fog and a brightness slider per biome, plus ones for the Mistlands mist, the Ashlands heat blur and cave haze.", null, true),
            new ModuleInfo(typeof(global::SmokeReducer.Plugin), "Smoke Reducer", "digi.valheim.smokereducer", "Less smoke from fires, less steam from ovens, fewer Ashlands fire puffs and a smaller dust cloud when you build, for better FPS and a clear view.", null, true),
            new ModuleInfo(typeof(global::PickableLights.Plugin), "Pickable Lights", "digi.valheim.pickablelights", "Glowing thistle, mushrooms, Jotun Puffs and Magecap stop adding real lights, for better FPS.", null, true),
            new ModuleInfo(typeof(global::HideWisp.Plugin), "Hide Wisp", "digi.valheim.hidewisp", "Off by default: your Wisplight no longer shows its wisp (no floating ball, no glow), but it still clears the mist around you.", null, false),
            new ModuleInfo(typeof(global::SoundLevels.Plugin), "Sound Levels", "digi.valheim.soundlevels", "Volume sliders for the shield generator's nonstop hum (20%) and the portals' hum (30%).", null, true),
            new ModuleInfo(typeof(global::PlantGrowthFix.Plugin), "Plant Growth Fix", "digi.valheim.plantgrowthfix", "Crops and saplings that look fully grown but never turn pickable (a vanilla bug) finish growing, without reloading the area.", null, true),
            new ModuleInfo(typeof(global::FarmPerformance.Plugin), "Farm Performance", "digi.valheim.farmperformance", "Big crop fields lag less: no crop shadows, fewer Green Thumb sparkles, and a whole field harvested or grown up at once no longer freezes the game.", null, true),
            new ModuleInfo(typeof(global::SmartSave.Plugin), "Smart Save", "digi.valheim.smartsave", "The autosave waits for a quiet moment instead of freezing the game mid-fight.", null, true),
            new ModuleInfo(typeof(global::SpawnerRestore.Plugin), "Spawner Restore", "digi.valheim.spawnerrestore", "A destroyed spawner leaves a see-through ghost where it stood: look at it and pay coins to bring the spawner back.", null, true),
            new ModuleInfo(typeof(global::QuietCleanup.Plugin), "Quiet Cleanup", "digi.valheim.quietcleanup", "Off by default, as measured it made freezes longer: holds Unity's memory cleanup back until a quiet moment, such as with a menu open or while you stand still.", null, false, true),
            new ModuleInfo(typeof(global::LagMeter.Plugin), "Lag Meter", "digi.valheim.lagmeter", "Finds out why the frame rate drops: times every engine system, script and mod, and reports each second below 40 fps (off by default).", null, false),
        };
    }
}
